/* Mãos em Oração — interactive visual prototype. All transactions are simulated. */
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const money=n=>Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',user:'M20 21v-2a7 7 0 0 0-14 0v2M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',bag:'M5 7h14l1 14H4L5 7ZM9 8V5a3 3 0 0 1 6 0v3',truck:'M1 4h13v12H1V4Zm13 4h4l4 4v4h-8M8 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0Zm12 0a2 2 0 1 1-4 0 2 2 0 0 1 4 0',box:'m12 2 9 5v10l-9 5-9-5V7l9-5Zm0 10 9-5M12 12 3 7m9 5v10M7 4.8l10 5.5',spark:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5L12 2Z',shield:'m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6l8-4Zm-4 10 3 3 5-6',plus:'M12 5v14M5 12h14',minus:'M5 12h14',close:'m6 6 12 12M6 18 18 6',check:'m4 12 5 5L20 6',card:'M2 5h20v14H2V5Zm0 5h20M6 15h3',pix:'m12 2 5 5-5 5-5-5 5-5Zm0 10 5 5-5 5-5-5 5-5ZM2 12l5-5 5 5-5 5-5-5Zm10 0 5-5 5 5-5 5-5-5',split:'M12 3v6M12 9 5 16m7-7 7 7M2 13v6h6m8 0h6v-6',lock:'M5 10h14v11H5V10Zm3 0V6a4 4 0 0 1 8 0v4m-4 5v2',leaf:'M20 3C7 1 2 9 7 15c6 6 14 0 13-12ZM4 21 16 7',chat:'M21 11a9 9 0 0 1-9 9c-2 0-4-.6-5.5-1.6L2 21l1.6-5A9 9 0 1 1 21 11ZM7 10h10M7 14h6',menu:'M3 6h18M3 12h18M3 18h18',cross:'M9 2h6v6h6v6h-6v8H9v-8H3V8h6V2Z',gift:'M3 8h18v4H3V8Zm2 4v9h14v-9m-7-4v13M12 8C3 8 4 0 9 3l3 5Zm0 0c9 0 8-8 3-5l-3 5',filter:'M4 6h16M7 12h10M10 18h4',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',logout:'M9 3H3v18h6m5-16 7 7-7 7M8 12h13'};
function icon(n){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.spark}"/></svg>`}
function logo(){return `<a class="brand" href="#/" aria-label="Mãos em Oração, início"><span class="brand-symbol" aria-hidden="true"></span><span class="brand-wordmark"><span>Mãos em</span><strong>Oração</strong></span></a>`}
const products=[
{id:'cruz-essencial',name:'Cruz Essencial',category:'Cristãos',tags:['Evangélicos','Cristãos','Presentes'],price:69.9,img:0,tag:'Design essencial',desc:'Linhas suaves, presença serena. Uma cruz contemporânea para trazer significado ao seu cantinho de oração ou à decoração de casa.',sizes:['15 cm','20 cm','25 cm'],colors:['Marfim','Areia','Terracota']},
{id:'nossa-senhora',name:'Nossa Senhora da Graça',category:'Católicos',tags:['Católicos','Presentes'],price:129.9,img:1,tag:'Coleção devoção',desc:'Uma interpretação delicada de Nossa Senhora, com formas acolhedoras e os detalhes táteis da impressão 3D.',sizes:['18 cm','25 cm','30 cm'],colors:['Marfim','Areia']},
{id:'espirito-santo',name:'Espírito Santo — Paz',category:'Cristãos',tags:['Cristãos','Católicos','Evangélicos','Presentes'],price:89.9,img:2,tag:'Para presentear',desc:'O símbolo da paz em uma escultura de asas abertas. Um detalhe cheio de significado para os espaços que você ama.',sizes:['15 cm','20 cm'],colors:['Marfim','Areia','Terracota']},
{id:'palavra-fe',name:'Palavra Fé',category:'Evangélicos',tags:['Evangélicos','Cristãos','Presentes','Personalizados'],price:49.9,img:3,tag:'Personalizável',desc:'Uma palavra pequena, um significado imenso. Tipografia escultural para lembrar, todos os dias, daquilo que sustenta você.',sizes:['12 cm','18 cm','24 cm'],colors:['Terracota','Marfim','Areia']},
{id:'sagrada-familia',name:'Sagrada Família — Abraço',category:'Católicos',tags:['Católicos','Presentes'],price:159.9,img:4,tag:'Coleção devoção',desc:'O encontro, o cuidado e o amor traduzidos em formas. Uma peça para celebrar a família e os novos começos.',sizes:['18 cm','25 cm'],colors:['Marfim','Areia']},
{id:'biblia-viva',name:'Bíblia Viva',category:'Evangélicos',tags:['Evangélicos','Cristãos','Personalizados'],price:79.9,img:5,tag:'Personalizável',desc:'Um símbolo da Palavra para acompanhar sua rotina. Escolha a dedicatória e transforme a peça em um presente pessoal.',sizes:['12 cm','18 cm'],colors:['Marfim','Areia','Terracota']}
];
const cats=['Todos','Católicos','Evangélicos','Cristãos','Presentes','Personalizados'];
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem('amago-'+key))??fallback}catch{return fallback}}
let cart=readStore('cart',[]),favs=readStore('favs',[]),customer=readStore('customer',null),orders=readStore('orders',[]);
let category='Todos',sort='featured',q='',material='Todos',maxPrice=250,detail={color:'',size:0,qty:1,engraving:'',view:0},checkout={step:1,shipping:'standard',payment:'pix',pix:50,installments:1,accepted:false,address:{},coupon:false},loginMode='login',lastOrder=null,toastTimer,lastFocus;
const persist=(key,val)=>{try{localStorage.setItem('amago-'+key,JSON.stringify(val))}catch{}};
const count=()=>cart.reduce((a,x)=>a+x.qty,0),sub=()=>cart.reduce((a,x)=>a+x.price*x.qty,0),discount=()=>checkout.coupon?Math.round(sub()*10)/100:0,ship=()=>checkout.shipping==='express'?29.9:18.9,total=()=>Math.round((sub()-discount()+ship())*100)/100;
function photo(idx,cls='',label=''){return `<div class="photo p${idx} ${cls}" role="img" aria-label="${esc(label||'Imagem conceitual da peça impressa em 3D')}"></div>`}
function crumb(parts){return `<div class="breadcrumb"><a href="#/">Início</a>${parts.map(p=>`${icon('chevron')}${p.href?`<a href="${p.href}">${esc(p.label)}</a>`:`<span>${esc(p.label||p)}</span>`}`).join('')}</div>`}
function header(){let route=location.hash||'#/';return `<div class="announcement"><div class="container row between"><span>Fé para viver. Amor para compartilhar.</span><span class="demo">Protótipo visual · compras e valores demonstrativos</span></div></div><header class="header"><div class="container header-main"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Abrir menu">${icon('menu')}</button>${logo()}<form class="search" id="search-form" role="search">${icon('search')}<input name="q" type="search" placeholder="Encontre uma peça com significado" aria-label="Buscar produtos" value="${esc(q)}"></form><div class="header-actions"><a class="icon-btn" href="#/favoritos" aria-label="Favoritos">${icon('heart')}${favs.length?`<span class="count">${favs.length}</span>`:''}</a><a class="account-link" href="#/conta" aria-label="Minha conta">${icon('user')}<span>${customer?`Olá, ${esc(customer.name.split(' ')[0])}`:'Minha conta'}</span></a><button class="icon-btn" data-action="cart" aria-label="Abrir carrinho com ${count()} itens">${icon('bag')}${count()?`<span class="count">${count()}</span>`:''}</button></div></div><div class="header-nav"><div class="container nav-inner"><nav class="nav-links" aria-label="Menu principal"><a href="#/produtos" class="${route==='#/produtos'?'current':''}">Todos os produtos</a>${cats.slice(1).map(c=>`<a href="#/categoria/${encodeURIComponent(c)}" class="${c==='Personalizados'?'special':''}">${c}</a>`).join('')}</nav><a class="nav-right" href="#/suporte">${icon('chat')}Precisa de ajuda?</a></div></div></header>`}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-grid"><div>${logo()}<p>A fé nos aproxima. O amor dá forma. Peças cristãs para acolher seu lar e tocar o coração de quem você ama.</p></div><div><h3>Explore a loja</h3><a href="#/produtos">Todos os produtos</a><a href="#/categoria/Católicos">Coleção católica</a><a href="#/categoria/Evangélicos">Coleção evangélica</a><a href="#/categoria/Personalizados">Personalizados</a></div><div><h3>Estamos por aqui</h3><a href="#/suporte">Central de ajuda</a><a href="#/suporte/entrega">Frete e entrega</a><a href="#/suporte/trocas">Trocas e devoluções</a><a href="#/suporte/cuidados">Cuidados com as peças</a></div><div><h3>Seu espaço</h3><a href="#/conta">Minha conta</a><a href="#/conta/pedidos">Meus pedidos</a><a href="#/favoritos">Meus favoritos</a><a href="#/suporte/privacidade">Privacidade e dados</a></div></div><div class="footer-bottom"><span>© 2026 Mãos em Oração · Marca e catálogo conceituais. Imagens geradas por IA.</span><span>Pix ${icon('pix')} &nbsp; Cartão ${icon('card')} &nbsp; Pagamento combinado ${icon('split')}</span></div></div></footer>`}
function card(p){return `<article class="product-card"><div class="product-image"><a href="#/produto/${p.id}" aria-label="Ver ${esc(p.name)}">${photo(p.img,'',p.name)}</a><span class="badge">${esc(p.tag)}</span><button class="icon-btn fav ${favs.includes(p.id)?'selected':''}" data-action="fav" data-id="${p.id}" aria-label="${favs.includes(p.id)?'Remover dos':'Adicionar aos'} favoritos: ${esc(p.name)}" aria-pressed="${favs.includes(p.id)}">${icon('heart')}</button><button class="icon-btn quick-add" data-action="quick" data-id="${p.id}" aria-label="Adicionar ${esc(p.name)} ao carrinho">${icon('plus')}</button></div><div class="product-info"><span class="category">${esc(p.category)} · impressão 3D</span><a href="#/produto/${p.id}"><h3>${esc(p.name)}</h3></a><div class="price">${money(p.price)} <small>ou 3× de ${money(p.price/3)}</small></div><div class="swatches" aria-label="Cores disponíveis">${p.colors.map(c=>`<i class="swatch" style="background:${colorHex(c)}" title="${c}"></i>`).join('')}</div></div></article>`}
function colorHex(c){return {Marfim:'#eee8db',Areia:'#cfc0a2',Terracota:'#b87150'}[c]||'#eee8db'}
function services(){return `<div class="service-strip"><div>${icon('box')}Peças feitas por impressão 3D</div><div>${icon('spark')}Personalize com seu significado</div><div>${icon('split')}Pix, cartão ou os dois juntos</div><div>${icon('truck')}Calcule a entrega no seu CEP</div></div>`}
