        <a class="devotion-card personal" href="#/categoria/Personalizados"><div class="devotion-text"><h3>Sua história.<br>Seu significado.</h3><span>Personalize seu presente ${icon('arrow')}</span></div>${photo(3,'','Palavra Fé em terracota')}</a>
      </div>
