const occasionData={
  oracao:{title:'Um cantinho. Um encontro com Deus.',desc:'Peças para acompanhar a leitura da Palavra, a oração e os seus momentos de silêncio.',ids:['cruz-essencial','nossa-senhora','biblia-viva','espirito-santo'],image:0},
  batismo:{title:'Para celebrar um novo começo.',desc:'Lembranças de fé e acolhimento para marcar o batismo e compartilhar esse momento especial.',ids:['espirito-santo','palavra-fe','cruz-essencial'],image:2},
  casamento:{title:'O amor também faz morada.',desc:'Um presente cheio de significado para celebrar o casamento, a família e a vida em um novo lar.',ids:['sagrada-familia','cruz-essencial','palavra-fe'],image:4},
  presentear:{title:'Um abraço em forma de presente.',desc:'Escolha uma lembrança para quem compartilha a caminhada da fé com você.',ids:products.filter(p=>p.tags.includes('Presentes')).map(p=>p.id),image:3}
};
function occasion(){return occasionData[decodeURIComponent((location.hash||'').split('/')[2]||'')]||null}
function catalogOpening(isHome,isFav){
  if(isFav)return `<div class="catalog-title"><div><h1>Seu lugar de guardar.</h1><p>As peças que tocaram o seu coração.</p></div></div>`;
  if(q)return `<div class="catalog-title"><div><h1>Busca por “${esc(q)}”</h1><p>Encontre um significado especial para levar com você.</p></div></div>`;
  const o=occasion();
  const content=o||({
    Católicos:{title:'A devoção mora nos detalhes.',desc:'Imagens sacras e símbolos para o seu cantinho de oração. Pequenas presenças que acolhem a fé.',image:1},
    Evangélicos:{title:'A Palavra inspira. A fé transforma.',desc:'Cruzes, símbolos e palavras para lembrar do amor de Cristo em cada novo dia.',image:5},
    Cristãos:{title:'Uma só fé. Muitos significados.',desc:'A cruz, a paz, a esperança. Símbolos cristãos para estar perto do que sustenta você.',image:0},
    Presentes:{title:'Tem amor que vira presente.',desc:'Para agradecer, celebrar ou simplesmente dizer: você está nas minhas orações.',image:4},
    Personalizados:{title:'Sua fé. Seu toque. Seu presente.',desc:'Escolha cor, tamanho e uma dedicatória na embalagem. Faça sua lembrança carregar um pouco da sua história.',image:3}
  }[category])||{title:'A fé faz parte da sua casa.',desc:'Objetos cristãos para viver a devoção, acolher o lar e presentear com amor.',image:0};
  return `<section class="faith-category ${category==='Personalizados'?'category-personal':category==='Evangélicos'?'category-evangelical':''}"><div class="faith-category-copy"><h1>${content.title}</h1><p>${content.desc}</p><div class="category-message">${icon(category==='Personalizados'?'gift':'heart')}${category==='Personalizados'?'Uma dedicatória pode dizer tanto.':'Para a sua caminhada. Para quem caminha com você.'}</div></div><div class="category-photo">${photo(content.image,'','Peça conceitual da coleção')}</div></section>`;
}
function filteredProducts(){let list=products.filter(p=>p.active!==false&&(!occasion()||occasion().ids.includes(p.id))&&(category==='Todos'||p.tags.includes(category))&&(!q||`${esc(p.name)} ${esc(p.desc)} ${esc(p.category)}`.toLocaleLowerCase('pt-BR').includes(q.toLocaleLowerCase('pt-BR')))&&(material==='Todos'||p.colors.includes(material))&&p.price<=maxPrice);if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));return list}
function catalog(isHome=false,isFav=false){let list=isFav?products.filter(p=>p.active!==false&&favs.includes(p.id)):filteredProducts();return `<main id="main" class="container catalog-page">${!isHome?crumb([{label:isFav?'Favoritos':occasion()?({'oracao':'Oração','batismo':'Batismo','casamento':'Casamento e família','presentear':'Para presentear'}[decodeURIComponent(location.hash.split('/')[2])]):category==='Todos'?'Produtos':category}]):''}${catalogOpening(isHome,isFav)}<div class="catalog-layout">${isFav?'':`<aside class="catalog-side" id="catalog-side" aria-label="Filtrar produtos"><div class="filter-group"><h3>Coleções</h3>${cats.map(c=>`<label class="filter-option"><input type="radio" name="category" value="${c}" ${category===c?'checked':''}>${c}<span class="muted">${c==='Todos'?products.length:products.filter(p=>p.tags.includes(c)).length}</span></label>`).join('')}</div><div class="filter-group"><h3>Cor da peça</h3>${['Todos','Marfim','Areia','Terracota'].map(c=>`<label class="filter-option"><input type="radio" name="material" value="${c}" ${material===c?'checked':''}>${c}</label>`).join('')}</div><div class="filter-group"><h3>Até ${money(maxPrice)}</h3><input type="range" min="50" max="250" step="10" value="${maxPrice}" id="price-range" aria-label="Preço máximo"><small class="muted">Valores de demonstração</small></div><button class="text-btn" data-action="clear-filters">Limpar filtros</button></aside>`}<div ${isFav?'style="grid-column:1/-1"':''}><div class="catalog-toolbar"><span class="muted">${list.length} ${list.length===1?'peça encontrada':'peças encontradas'}</span>${!isFav?`<button class="btn secondary small mobile-filter" data-action="filter">${icon('filter')}Filtros</button><form id="catalog-search" class="row" style="gap:8px"><input type="search" name="q" aria-label="Buscar no catálogo" placeholder="Buscar peça" value="${esc(q)}" style="max-width:200px;min-height:40px;font-size:.77rem"><button class="icon-btn" aria-label="Buscar">${icon('search')}</button></form><select id="sort" aria-label="Ordenar produtos"><option value="featured" ${sort==='featured'?'selected':''}>Em destaque</option><option value="low" ${sort==='low'?'selected':''}>Menor preço</option><option value="high" ${sort==='high'?'selected':''}>Maior preço</option><option value="name" ${sort==='name'?'selected':''}>Nome: A a Z</option></select>`:''}</div>${list.length?`<div class="product-grid">${list.map(card).join('')}</div>`:`<div class="empty">${icon(isFav?'heart':'search')}<h2>${isFav?'Guarde o que toca você.':'Nenhuma peça por aqui.'}</h2><p>${isFav?'Toque no coração de uma peça para encontrá-la aqui depois.':'Tente outro termo ou remova os filtros para encontrar sua peça.'}</p><a href="#/produtos" class="btn" data-action="${isFav?'navigate':'clear-filters'}">${isFav?'Explorar produtos':'Limpar filtros'}</a></div>`}</div></div></main>`}
function productPage(id){const p=products.find(x=>x.id===id);if(!p||p.active===false)return missing();if(!detail.color||!p.colors.includes(detail.color))detail.color=p.colors[0];return `<main id="main" class="container page-top">${crumb([{label:'Produtos',href:'#/produtos'},{label:p.name}])}<section class="product-detail"><div><div class="gallery-main">${photo(p.img,'',p.name)}<span class="badge">Imagem conceitual · ${detail.view===0?'peça completa':'aproximação do acabamento'}</span></div><div class="gallery-thumbs"><button class="${detail.view===0?'active':''}" data-action="view" data-view="0" aria-label="Ver peça inteira">${photo(p.img)}</button><button class="${detail.view===1?'active':''}" data-action="view" data-view="1" aria-label="Aproximar textura da peça">${photo(p.img,'','Detalhe aproximado do acabamento')}</button></div><p class="muted" style="font-size:.72rem;margin-top:14px">Imagem ilustrativa gerada por IA. As cores e proporções são conceituais.</p></div><div class="detail-copy"><h1>${esc(p.name)}</h1><span class="badge olive" style="margin-bottom:18px">${esc(p.category)} · ${esc(p.tag)}</span><p>${esc(p.desc)}</p><div class="detail-price" id="detail-price">${money(p.price+detail.size*20)}</div><small id="detail-installments">ou 3× de ${money((p.price+detail.size*20)/3)} sem juros · valores ilustrativos</small><div class="detail-options"><div><span class="option-label">Cor: <strong id="color-name">${detail.color}</strong></span><div class="color-buttons">${p.colors.map(c=>`<button class="color-button ${detail.color===c?'selected':''}" data-action="color" data-color="${c}" aria-pressed="${detail.color===c}"><i style="background:${colorHex(c)}"></i>${c}</button>`).join('')}</div></div><label>Tamanho<select id="product-size">${p.sizes.map((s,i)=>`<option value="${i}" ${detail.size===i?'selected':''}>${s}${i?` (+ ${money(i*20)})`:''}</option>`).join('')}</select></label>${p.tags.includes('Personalizados')?`<label>Dedicatória na embalagem <span class="muted">(opcional, até 40 caracteres)</span><input id="engraving" maxlength="40" value="${esc(detail.engraving)}" placeholder="Ex.: Com amor, para a vovó"></label>`:''}<div class="buy-row"><div class="quantity"><button data-action="detail-minus" aria-label="Diminuir quantidade" ${detail.qty<=1?'disabled':''}>−</button><span id="detail-qty">${detail.qty}</span><button data-action="detail-plus" aria-label="Aumentar quantidade" ${detail.qty>=10?'disabled':''}>+</button></div><button class="btn full" data-action="add" data-id="${p.id}">${icon('bag')}Adicionar ao carrinho</button></div><button class="btn secondary full" data-action="buy" data-id="${p.id}">Comprar agora ${icon('arrow')}</button></div><div class="shipping-box"><form id="product-shipping"><label for="product-cep">${icon('truck')}Calcule o frete e o prazo</label><div class="row"><input id="product-cep" name="cep" inputmode="numeric" maxlength="9" placeholder="00000-000" aria-label="CEP para calcular frete" required pattern="[0-9]{5}-?[0-9]{3}"><button class="btn secondary small">Calcular</button></div><div class="shipping-result" id="shipping-result" aria-live="polite"></div></form></div><div class="details-list"><details open><summary>Sobre a peça</summary><p>Conceito em PLA com acabamento fosco e textura de camadas. Base incluída. Tamanho selecionado: ${p.sizes[detail.size]||p.sizes[0]}. Produção sob encomenda simulada neste protótipo.</p></details><details><summary>Cuidados e conservação</summary><p>Limpe com pano macio e seco. Evite calor intenso, sol direto e umidade. Peça decorativa; mantenha fora do alcance de crianças pequenas.</p></details><details><summary>Personalização e entrega</summary><p>Escolha cor e tamanho antes de adicionar. Prazos e fretes exibidos são demonstrativos e incluem uma estimativa de produção. Nenhuma encomenda real será gerada.</p></details></div></div></section><section class="section"><div class="section-header"><h2>Outras formas de sentir.</h2><a class="arrow-link" href="#/produtos">Explorar todas ${icon('arrow')}</a></div><div class="product-grid">${products.filter(x=>x.id!==id&&x.active!==false).slice(0,4).map(card).join('')}</div></section></main>`}
function addProduct(id,quick=false){let p=products.find(x=>x.id===id);if(!p||p.active===false)return;const color=quick?p.colors[0]:detail.color,size=quick?0:detail.size,qty=quick?1:detail.qty,engraving=quick?'':detail.engraving;const key=[id,color,size,engraving].join('|');let existing=cart.find(x=>x.key===key);if(existing)existing.qty=Math.min(10,existing.qty+qty);else cart.push({key,id,name:p.name,img:p.img,color,size:p.sizes[size],price:p.price+size*20,qty,engraving});persist('cart',cart);updateCount()}
function updateCount(){const cartButton=$('[data-action=cart]');if(cartButton){cartButton.setAttribute('aria-label',`Abrir carrinho com ${count()} itens`);$('.count',cartButton)?.remove();if(count())cartButton.insertAdjacentHTML('beforeend',`<span class="count">${count()}</span>`)}}
function cartRows(simple=false){return cart.map((x,i)=>`<div class="cart-item">${photo(x.img,'',x.name)}<div><a href="#/produto/${x.id}" data-action="close-link"><h3>${x.name}</h3></a><small>${x.color} · ${x.size}${simple?` · ${x.qty} un.`:''}</small>${x.engraving?`<small>“${esc(x.engraving)}”</small>`:''}${simple?`<small>${money(x.price*x.qty)}</small>`:`<div class="row between"><div class="quantity"><button data-action="cart-minus" data-index="${i}" aria-label="Diminuir quantidade de ${x.name}" ${x.qty<=1?'disabled':''}>−</button><span>${x.qty}</span><button data-action="cart-plus" data-index="${i}" aria-label="Aumentar quantidade de ${x.name}" ${x.qty>=10?'disabled':''}>+</button></div><strong style="font-size:.82rem">${money(x.price*x.qty)}</strong></div><button class="remove" data-action="remove" data-index="${i}">Remover</button>`}</div></div>`).join('')}
function openCart(){lastFocus=document.activeElement;$('#overlay-root').innerHTML=`<div class="overlay" data-action="backdrop"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="cart-title"><div class="drawer-header"><h2 id="cart-title">Seu carrinho <span class="muted">(${count()})</span></h2><button class="icon-btn" data-action="close" aria-label="Fechar carrinho">${icon('close')}</button></div><div class="drawer-content">${cart.length?`<div class="notice">Cada peça, um significado. Confira suas escolhas.</div>${cartRows()}`:`<div class="empty">${icon('bag')}<h2>Um espaço para sua fé.</h2><p>Seu carrinho ainda está vazio. Que tal encontrar uma peça especial?</p><a class="btn" href="#/produtos" data-action="close-link">Explorar produtos</a></div>`}</div>${cart.length?`<div class="drawer-footer"><div class="money-line"><span>Subtotal</span><strong>${money(sub())}</strong></div><small>Frete calculado no próximo passo.</small><a class="btn full" href="#/checkout" data-action="close-link">Ir para o checkout ${icon('arrow')}</a><button class="text-btn" data-action="close" style="display:block;margin:10px auto 0">Continuar explorando</button><small>Compra simulada · nenhum valor será cobrado</small></div>`:''}</section></div>`;document.body.style.overflow='hidden';$('.drawer [data-action=close]').focus()}
function closeOverlay(){if(typeof disposeFaithViewer==='function')disposeFaithViewer();let previous=lastFocus;$('#overlay-root').innerHTML='';document.body.style.overflow='';if(previous?.isConnected)previous.focus()}
function checkoutHeader(){return `<header class="checkout-head"><div class="container">${logo()}<span class="secure">${icon('lock')}Checkout demonstrativo</span></div></header>`}
function summary(){return `<aside class="summary"><h2>Suas escolhas</h2>${cartRows(true)}<form id="coupon-form" class="coupon"><input name="coupon" placeholder="Cupom de demonstração" aria-label="Cupom de desconto" value="${checkout.coupon?'PRIMEIRAFE':''}"><button class="btn secondary small">Aplicar</button></form><small>Experimente PRIMEIRAFE para simular 10% de desconto.</small><div style="margin-top:22px"><div class="money-line"><span>Produtos</span><span>${money(sub())}</span></div>${checkout.coupon?`<div class="money-line"><span>Desconto de demonstração</span><span>− ${money(discount())}</span></div>`:''}<div class="money-line"><span>Entrega ${checkout.shipping==='express'?'expressa':'padrão'}</span><span>${money(ship())}</span></div><div class="money-line total"><span>Total</span><span>${money(total())}</span></div></div><small>Todos os valores são ilustrativos. Nenhum pedido ou pagamento real será realizado.</small></aside>`}
function checkoutPage(){if(!cart.length)return `<main id="main" class="container"><div class="empty">${icon('bag')}<h1 style="font-size:2rem">Seu carrinho está vazio.</h1><p>Escolha uma peça para experimentar o checkout.</p><a href="#/produtos" class="btn">Explorar produtos</a></div></main>`;const a=checkout.address;return `<main id="main" class="container"><div class="checkout-layout"><section><a class="arrow-link" href="#/produtos">${icon('chevron')}Voltar para a loja</a><h1>Quase na sua casa.</h1><div class="steps">${['Seus dados','Entrega','Pagamento'].map((s,i)=>`<span class="${checkout.step===i+1?'active':checkout.step>i+1?'done':''}"><b>${checkout.step>i+1?'✓':i+1}</b>${s}</span>`).join('')}</div><div style="margin-top:25px">${checkout.step===1?`<div class="notice" style="margin-bottom:22px">Este é um protótipo. Use os dados fictícios para testar o fluxo.</div><button class="text-btn" data-action="fill-demo" style="margin-bottom:22px">Preencher com dados fictícios</button><form id="address-form"><div class="form-grid"><label class="span2">Nome completo<input name="name" autocomplete="off" required minlength="3" value="${esc(a.name||'')}" placeholder="Nome de demonstração"></label><label class="span2">E-mail<input name="email" type="email" autocomplete="off" required value="${esc(a.email||'')}" placeholder="cliente@exemplo.com"></label><label>CEP<input name="cep" inputmode="numeric" required pattern="[0-9]{5}-?[0-9]{3}" maxlength="9" value="${esc(a.cep||'')}" placeholder="00000-000"></label><label>Telefone fictício<input name="phone" inputmode="tel" required pattern="[0-9 ()+\-]{10,20}" value="${esc(a.phone||'')}" placeholder="(11) 99999-0000"></label><label class="span2">Rua ou avenida<input name="street" required value="${esc(a.street||'')}" placeholder="Rua Exemplo"></label><label>Número<input name="number" required value="${esc(a.number||'')}" placeholder="123"></label><label>Complemento<input name="extra" value="${esc(a.extra||'')}" placeholder="Opcional"></label><label>Bairro<input name="district" required value="${esc(a.district||'')}" placeholder="Centro"></label><label>Cidade<input name="city" required value="${esc(a.city||'')}" placeholder="São Paulo"></label><label>Estado<select name="state" required><option value="">Selecione</option>${['AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO'].map(s=>`<option ${a.state===s?'selected':''}>${s}</option>`).join('')}</select></label></div><div class="form-actions"><span class="muted" style="font-size:.74rem">Dados apenas nesta sessão.</span><button class="btn">Escolher entrega ${icon('arrow')}</button></div></form>`:checkout.step===2?`<h2 style="font-size:1.35rem;margin-bottom:12px">Como sua peça chega até você?</h2><p class="muted" style="font-size:.83rem;margin-bottom:20px">${esc(a.street)}, ${esc(a.number)} · ${esc(a.city)}/${esc(a.state)} · CEP ${esc(a.cep)}</p>${[['standard','Entrega padrão','Produção + entrega: 8 a 12 dias úteis',18.9],['express','Entrega expressa','Produção + entrega: 5 a 7 dias úteis',29.9]].map(([id,title,desc,price])=>`<label class="radio-card ${checkout.shipping===id?'active':''}"><input type="radio" name="shipping" value="${id}" ${checkout.shipping===id?'checked':''}><span class="grow"><strong>${title}</strong><small>${desc}</small></span><strong>${money(price)}</strong></label>`).join('')}<div class="notice" style="margin-top:20px">Fretes e prazos simulados para o CEP informado. O prazo exibido inclui uma produção estimada.</div><div class="form-actions"><button class="text-btn" data-action="checkout-back">Voltar aos dados</button><button class="btn" data-action="checkout-next">Ir para pagamento ${icon('arrow')}</button></div>`:paymentPage()}</div></section>${summary()}</div></main>`}
function paymentPage(){const amount=total();let pix=checkout.payment==='split'?Math.min(amount-.01,Math.max(.01,Number(checkout.pix)||.01)):amount;let cardAmount=checkout.payment==='split'?amount-pix:amount;return `<h2 style="font-size:1.35rem">Do seu jeito, até no pagamento.</h2><div class="payment-tabs" role="group" aria-label="Forma de pagamento">${[['pix','Pix','pix'],['card','Cartão','card'],['split','Pix + cartão','split']].map(([id,label,ic])=>`<button class="${checkout.payment===id?'active':''}" data-action="payment" data-payment="${id}" aria-pressed="${checkout.payment===id}">${icon(ic)}${label}</button>`).join('')}</div><div class="payment-panel">${checkout.payment==='pix'?`<h2>Prático, com Pix.</h2><p>Ao confirmar, você verá a tela de pagamento Pix de demonstração. O total será ${money(amount)}.</p><div class="notice" style="margin-top:20px">Nenhum QR Code de cobrança real é gerado.</div>`:`${checkout.payment==='split'?`<h2>Uma parte no Pix. O restante no cartão.</h2><p>Defina quanto quer pagar agora no Pix. O saldo é atualizado automaticamente.</p><div class="split-numbers"><label class="split-box"><small>Valor no Pix</small><input id="split-amount" type="number" min="0.01" max="${(amount-.01).toFixed(2)}" step=".01" value="${pix.toFixed(2)}" aria-label="Valor a pagar no Pix"></label><div class="split-box"><small>Saldo no cartão</small><strong id="split-card-total">${money(cardAmount)}</strong></div></div><p id="split-error" class="form-error" aria-live="polite"></p>`:`<h2>Seu cartão, em até 3 vezes.</h2><p>Para testar com segurança, use o cartão de demonstração abaixo.</p>`}<div class="demo-card">${icon('card')}<div><strong>Cartão de teste ···· 4242</strong><small>Cliente demonstração · aprovação simulada</small></div>${icon('check')}</div><label>Parcelamento<select id="installments">${[1,2,3].map(n=>`<option value="${n}" ${Number(checkout.installments)===n?'selected':''}>${n}× de ${money(cardAmount/n)} sem juros</option>`).join('')}</select></label><small class="muted" style="display:block;margin-top:10px">Não informe número de cartão, validade ou CVV reais.</small>`}</div><label class="check-line"><input type="checkbox" id="accept-demo" ${checkout.accepted?'checked':''}>Entendi que esta compra é uma simulação.</label><p class="form-error" id="payment-error" aria-live="polite"></p><div class="form-actions"><button class="text-btn" data-action="checkout-back">Voltar à entrega</button><button class="btn" data-action="place-order">${checkout.payment==='card'?'Confirmar compra simulada':'Gerar Pix de demonstração'} ${icon('arrow')}</button></div>`}
function successPage(){let o=lastOrder||orders[0];if(!o)return missing();const pending=o.status==='Aguardando Pix';return `<main id="main" class="container"><section class="success"><div class="success-icon">${icon(pending?'pix':'check')}</div><h1>${pending?'Falta só o seu Pix.':'Sua escolha ganhou forma.'}</h1><p>${pending?'Pedido de demonstração reservado. Simule a confirmação para continuar.':'Compra de demonstração confirmada. Obrigado por explorar a Mãos em Oração.'}</p><span class="badge olive" style="margin-top:17px">Pedido ${o.number} · ${o.status}</span><div class="success-panel">${pending?`<h2>Pix de demonstração · ${money(o.pix)}</h2><p class="muted" style="font-size:.83rem;margin-top:12px">Esta área representa a cobrança Pix. Para evitar uma cobrança real, não há QR Code nem chave de pagamento.</p><div style="padding:24px 0;display:flex;gap:18px;align-items:center">${icon('pix')}<code style="font-size:.8rem;overflow-wrap:anywhere">MAOS-EM-ORACAO-DEMONSTRACAO-SEM-VALOR</code></div><button class="btn full" data-action="confirm-pix">Simular pagamento do Pix ${icon('check')}</button>${o.payment==='split'?`<p class="muted" style="font-size:.78rem;margin-top:15px">O saldo de ${money(o.card)} será aprovado no cartão de teste em ${o.installments}× de ${money(o.card/o.installments)} após esta confirmação.</p>`:''}`:`<h2>Tudo certo com o seu pedido.</h2><div class="money-line" style="margin-top:20px"><span>Total da simulação</span><strong>${money(o.total)}</strong></div><p class="muted" style="font-size:.83rem">${o.payment==='split'?`Pix: ${money(o.pix)} + cartão: ${money(o.card)} em ${o.installments}×.`:o.payment==='pix'?'Pagamento Pix simulado.':`Cartão de teste em ${o.installments}× de ${money(o.total/o.installments)}.`}</p><p class="muted" style="font-size:.83rem;margin-top:12px">Entrega demonstrativa para ${esc(o.address.city)}/${esc(o.address.state)}. Nenhum produto será enviado.</p>`}</div><div class="row" style="justify-content:center;margin-top:27px;flex-wrap:wrap"><a href="#/conta/pedidos" class="btn">Ver meus pedidos ${icon('arrow')}</a><a href="#/produtos" class="btn secondary">Continuar explorando</a></div></section></main>`}
function loginPage(){return typeof authPage==='function'?authPage('customer'):'<main id="main" class="container"><p>Preparando seu acesso…</p></main>'}
function accountPage(tab='overview'){if(!customer)return loginPage();let nav=[['overview','Meu espaço','user'],['pedidos','Meus pedidos','box'],['enderecos','Endereços','pin'],['dados','Meus dados','user']];return `<main id="main" class="container"><div class="account-layout"><aside class="account-side"><h2>Olá, ${esc(customer.name.split(' ')[0])}.</h2><p>Que bom ter você por aqui.</p>${nav.map(([id,label,ic])=>`<a href="#/conta/${id}" class="${tab===id?'active':''}">${icon(ic)}${label}</a>`).join('')}<a href="#/favoritos">${icon('heart')}Favoritos</a><button data-action="logout">${icon('logout')}Sair</button></aside><section class="account-content">${['assinatura','envios','cobrancas','atendimentos'].includes(tab)&&typeof accountClubContent==='function'?accountClubContent(tab):tab.startsWith('pedido-')?orderDetail(tab.slice(7)):tab==='dados'?`<h1>Seus dados.</h1><p>Atualize seu perfil de demonstração.</p><form id="profile-form" class="form-grid" style="max-width:600px"><label class="span2">Nome<input name="name" required minlength="2" value="${esc(customer.name)}"></label><label class="span2">E-mail fictício<input name="email" type="email" required value="${esc(customer.email)}"></label><button class="btn">Salvar alterações</button></form>`:tab==='enderecos'?`<h1>Seu lugar no mundo.</h1><p>Endereço de demonstração para os seus pedidos.</p><form id="saved-address-form" class="form-grid" style="max-width:600px"><label class="span2">Rua e número<input name="street" required value="${esc(customer.address?.street||'Rua Exemplo, 123')}"></label><label>Cidade<input name="city" required value="${esc(customer.address?.city||'São Paulo')}"></label><label>CEP<input name="cep" required pattern="[0-9]{5}-?[0-9]{3}" value="${esc(customer.address?.cep||'01001-000')}"></label><button class="btn">Salvar endereço fictício</button></form>`:tab==='pedidos'?`<h1>Seus pedidos.</h1><p>Acompanhe cada escolha, da impressão até a sua casa.</p>${orderList()}`:`<h1>Olá, ${esc(customer.name.split(' ')[0])}.</h1><p>Um cantinho para acompanhar suas escolhas e encontrar novos significados.</p><div class="notice">Conta de demonstração · dados e pedidos guardados neste navegador.</div><div class="section-header" style="margin-top:35px"><h2 style="font-size:1.4rem">Pedidos recentes</h2><a class="arrow-link" href="#/conta/pedidos">Ver todos ${icon('arrow')}</a></div>${orderList(2)}<a class="btn secondary" style="margin-top:25px" href="#/produtos">Encontrar uma nova peça ${icon('arrow')}</a>`}</section></div></main>`}
function orderList(limit=99){return orders.length?orders.slice(0,limit).map(o=>`<article class="order-row"><div class="row between wrap"><h3>${o.number}</h3><span class="badge ${o.status==='Aguardando Pix'?'terra':'olive'}">${o.status}</span></div><p>${esc(o.date)} · ${o.items.reduce((a,x)=>a+x.qty,0)} peça(s) · ${money(o.total)}</p><div class="row between wrap"><div class="order-preview">${o.items.slice(0,3).map(x=>photo(x.img,'',x.name)).join('')}</div><a class="arrow-link" href="#/conta/pedido-${o.id}">Ver pedido ${icon('arrow')}</a></div></article>`).join(''):`<div class="empty">${icon('box')}<h2>A sua história começa aqui.</h2><p>Seus pedidos aparecerão aqui depois de uma compra de demonstração.</p><a href="#/produtos" class="btn">Explorar produtos</a></div>`}
function orderDetail(id){let o=orders.find(x=>x.id===id);if(!o)return `<h1>Pedido não encontrado.</h1><a href="#/conta/pedidos" class="text-btn">Voltar aos pedidos</a>`;return `<a href="#/conta/pedidos" class="arrow-link">Voltar aos pedidos</a><h1 style="margin-top:22px">Pedido ${o.number}.</h1><p>Simulação criada em ${esc(o.date)}.</p><span class="badge olive">${o.status}</span>${typeof storeShipmentContent==='function'?storeShipmentContent(o):''}<div class="tracking legacy-tracking">${['Pedido recebido','Em produção','Enviado','Entregue'].map((s,i)=>`<div class="${i===0?'done':''}">${s}<small>${i===0?'Etapa atual':'Etapa ilustrativa'}</small></div>`).join('')}</div>${o.items.map(x=>`<div class="cart-item">${photo(x.img,'',x.name)}<div><h3>${x.name}</h3><small>${x.color} · ${x.size} · ${x.qty} un.</small><small>${money(x.price*x.qty)}</small></div></div>`).join('')}<div class="money-line total"><span>Total</span><strong>${money(o.total)}</strong></div><p class="muted" style="font-size:.84rem">Entrega: ${esc(o.address.street)}, ${esc(o.address.number)} · ${esc(o.address.city)}/${esc(o.address.state)}</p>${o.status==='Aguardando Pix'?`<button class="btn" style="margin-top:20px" data-action="resume-pix" data-id="${o.id}">Ver Pix de demonstração</button>`:''}<a href="#/suporte" class="btn secondary" style="margin-top:20px">${icon('chat')}Preciso de ajuda</a>`}
const faqs=[['Como funciona a impressão 3D?','O conceito utiliza camadas de PLA para criar peças decorativas. As linhas sutis da impressão fazem parte da textura. O catálogo exibido é ilustrativo.'],['Posso pagar uma parte no Pix e outra no cartão?','Sim, neste protótipo. No checkout, escolha “Pix + cartão”, defina a parte no Pix e divida o restante em até 3 parcelas. A confirmação é simulada.'],['Como funciona a entrega?','Informe um CEP válido para ver duas opções demonstrativas. Os prazos incluem uma estimativa de produção. Uma loja real precisará integrar transportadora e regras por região.'],['É possível personalizar minha peça?','Todas as peças possuem opções de cor e tamanho no protótipo. As peças da coleção Personalizados também permitem uma dedicatória na embalagem.'],['Como funcionam trocas e devoluções?','Esta é uma experiência de demonstração e não gera compras reais. A política comercial deverá ser definida pelo lojista antes do lançamento.'],['Como cuidar das peças?','Use um pano macio e seco. Evite calor, sol direto e produtos abrasivos. Os objetos apresentados são conceitos decorativos.'],['Quais dados ficam salvos?','Favoritos, carrinho, perfil fictício e pedidos simulados ficam no armazenamento local deste navegador. Dados de cartão não são solicitados. Você pode apagar os dados de demonstração abaixo.']];
function supportPage(topic=''){const map={entrega:2,trocas:4,cuidados:5,privacidade:6};return `<main id="main" class="container"><div class="support-title"><h1>Como podemos ajudar?</h1><p>Da escolha da peça aos detalhes da entrega, encontre o que precisa para seguir com tranquilidade.</p></div><div class="support-layout"><section><h2>Respostas que aproximam.</h2><div class="details-list" style="margin-top:0">${faqs.map(([t,d],i)=>`<details ${map[topic]===i?'open':''}><summary>${t}</summary><p>${d}</p></details>`).join('')}</div><button class="text-btn" data-action="reset-data" style="margin-top:22px">Apagar meus dados de demonstração</button></section><section class="support-form"><h2>Vamos conversar.</h2><p>Simule um atendimento. Sua mensagem fica neste navegador e no painel de demonstração. Nenhuma mensagem é enviada.</p><form id="support-form"><label>Seu nome fictício<input name="name" required placeholder="Como podemos chamar você?"></label><label>E-mail de demonstração<input name="email" type="email" required placeholder="cliente@exemplo.com"></label><label>Sobre o que você quer falar?<select name="topic"><option>Uma peça ou personalização</option><option>Meu pedido</option><option>Pagamento</option><option>Entrega</option><option>Outro assunto</option></select></label><label>Mensagem<textarea name="message" required minlength="8" placeholder="Conte um pouco sobre o que você precisa."></textarea></label><button class="btn full">Simular envio ${icon('arrow')}</button></form><div id="support-result" aria-live="polite"></div></section></div></main>`}
function missing(){return `<main id="main" class="container"><div class="empty">${icon('search')}<h1 style="font-size:2rem">Este caminho ainda não tem uma peça.</h1><p>Volte à loja para continuar explorando.</p><a class="btn" href="#/produtos">Ver produtos</a></div></main>`}
