document.addEventListener('keydown',e=>{const dialog=$('[role=dialog]');if(!dialog)return;if(e.key==='Escape'){e.preventDefault();closeOverlay()}if(e.key==='Tab'){const items=$$('a[href],button:not([disabled]),input,select,textarea',dialog).filter(x=>x.offsetParent!==null);if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0]?.focus()}}});
